/**
 * Payment Reports page: organisation, period and transaction filters, summary, charts, transaction list, detail and
 * exports. Reuses the dashboard components; every request is checked again on the server.
 *
 * @module     report_orgreports/payments
 * @copyright  2026
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('report_orgreports/payments', ['core/ajax', 'report_orgreports/format', 'report_orgreports/metric_cards', 'report_orgreports/chart_panel',
        'report_orgreports/data_table', 'report_orgreports/date_filter', 'report_orgreports/transaction_detail'],
function(Ajax, F, Cards, Charts, Tables, DateFilter, Detail) {
    'use strict';

    var TABLE = 'payments';
    var FILTERS = ['status', 'method', 'courseid', 'planid', 'search'];

    var root;
    var state;
    var table = {sort: '', dir: 'DESC', page: 0, perpage: 25};
    var requestid = 0;

    /**
     * Call a web service and parse its JSON payload.
     *
     * @param {String} name
     * @param {Object} args
     * @returns {Promise}
     */
    var call = function(name, args) {
        return Ajax.call([{methodname: name, args: args}])[0].then(function(result) {
            if (!result || typeof result.json !== 'string') {
                throw new Error('unexpected response from ' + name);
            }
            return JSON.parse(result.json);
        });
    };

    /**
     * Organisation, period and transaction filters of the current state.
     *
     * @returns {Object}
     */
    var args = function() {
        var custom = state.range === 'custom';
        return {org: state.org, range: state.range, from: custom ? state.from : '', to: custom ? state.to : '',
            status: state.filters.status, method: state.filters.method, courseid: state.filters.courseid,
            planid: state.filters.planid, search: state.filters.search};
    };

    /**
     * Keep the address bar in step with the filters.
     */
    var updateUrl = function() {
        var a = args();
        var params = new URLSearchParams();
        Object.keys(a).forEach(function(k) {
            if (a[k] !== '' && !(k !== 'org' && a[k] === 0)) {
                params.set(k, String(a[k]));
            }
        });
        window.history.replaceState(null, '', F.config().pageurl + '?' + params.toString());
    };

    /**
     * Download URL with every filter.
     *
     * @param {String} format
     * @returns {String}
     */
    var exportUrl = function(format) {
        var a = Object.assign(args(), {kind: 'payments', format: format, sort: table.sort, dir: table.sort ? table.dir : ''});
        var params = new URLSearchParams();
        Object.keys(a).forEach(function(k) {
            if (a[k] !== '' && !(k !== 'org' && a[k] === 0)) {
                params.set(k, String(a[k]));
            }
        });
        params.set('sesskey', M.cfg.sesskey);
        return F.config().exporturl + '?' + params.toString();
    };

    /**
     * Fill the export menu.
     */
    var buildExportMenu = function() {
        var list = root.querySelector('[data-region="exportlist"]');
        if (!list) {
            return;
        }
        var item = function(href, icon, title, desc) {
            return '<a href="' + F.esc(href) + '" role="menuitem" class="orgr-menu-item"><i class="fa-solid ' + icon +
                '" aria-hidden="true"></i><span><strong>' + F.esc(title) + '</strong><small>' + F.esc(desc) +
                '</small></span></a>';
        };
        list.innerHTML = item(exportUrl('csv'), 'fa-file-csv', F.str('pexportcsv'), F.str('pexportcsv_desc')) +
            item(exportUrl('pdf'), 'fa-file-pdf', F.str('pexportpdf'), F.str('pexportpdf_desc'));
    };

    /**
     * Open or close the export menu.
     *
     * @param {Boolean} open
     */
    var toggleMenu = function(open) {
        var region = root.querySelector('[data-region="export"]');
        if (!region) {
            return;
        }
        if (open) {
            buildExportMenu();
        }
        region.querySelector('[data-region="exportlist"]').hidden = !open;
        region.querySelector('[data-action="menu"]').setAttribute('aria-expanded', open ? 'true' : 'false');
    };

    /**
     * Fill a filter select, keeping only options the server offers; hide filters without options.
     *
     * @param {String} key
     * @param {Array} options [{value, label}]
     * @param {String} alllabel
     */
    var fillSelect = function(key, options, alllabel) {
        var select = root.querySelector('[data-pfilter="' + key + '"]');
        var wrapper = root.querySelector('[data-region="filter-' + key + '"]');
        var value = String(state.filters[key] || '');
        select.innerHTML = '<option value="">' + F.esc(alllabel) + '</option>' + options.map(function(o) {
            return '<option value="' + F.esc(o.value) + '"' + (String(o.value) === value ? ' selected' : '') + '>' +
                F.esc(F.decode(o.label)) + '</option>';
        }).join('');
        wrapper.classList.toggle('d-none', !options.length && !value);
    };

    /**
     * Show the filter options and the filters the server accepted.
     *
     * @param {Object} filters
     */
    var renderFilters = function(filters) {
        // The server drops values that are not valid for this organisation: keep the state in step.
        state.filters.status = filters.applied.status || '';
        state.filters.method = filters.applied.method || '';
        state.filters.courseid = F.toNumber(filters.applied.courseid);
        state.filters.planid = F.toNumber(filters.applied.planid);
        fillSelect('status', filters.statuses, F.str('allstatuses'));
        fillSelect('method', filters.methods, F.str('allmethods'));
        fillSelect('courseid', filters.courses, F.str('allcourses'));
        fillSelect('planid', filters.plans, F.str('allplans'));
        var active = FILTERS.some(function(k) {
            return state.filters[k] !== '' && state.filters[k] !== 0;
        });
        root.querySelector('[data-action="resetfilters"]').classList.toggle('orgr-btn-soft', active);
    };

    /**
     * Busy indicator.
     *
     * @param {Boolean} busy
     */
    var setBusy = function(busy) {
        root.classList.toggle('orgr-busy', busy);
        root.querySelector('[data-region="body"]').setAttribute('aria-busy', busy ? 'true' : 'false');
        var refresh = root.querySelector('[data-action="refresh"]');
        refresh.classList.toggle('spinning', busy);
        refresh.disabled = busy;
    };

    /**
     * Load the transaction list page.
     */
    var loadTable = function() {
        var wrapper = root.querySelector('[data-table="' + TABLE + '"]');
        if (!wrapper) {
            return;
        }
        var body = wrapper.querySelector('[data-region="tablebody"]');
        body.classList.add('orgr-dim');
        body.setAttribute('aria-busy', 'true');
        var mine = requestid;
        var a = args();
        call('report_orgreports_get_table', {org: a.org, table: TABLE, range: a.range, from: a.from, to: a.to,
            search: a.search, courseid: a.courseid, status: a.status, method: a.method, planid: a.planid,
            sort: table.sort, dir: table.dir, page: table.page, perpage: table.perpage}).then(function(data) {
            if (mine !== requestid) {
                return;
            }
            var filtered = FILTERS.some(function(k) {
                return state.filters[k] !== '' && state.filters[k] !== 0;
            });
            // Status cells become badges with an icon and label.
            (data.rows || []).forEach(function(r) {
                (r.cells || []).forEach(function(cell) {
                    if (cell.badge) {
                        cell.value = Detail.badge(cell.badge, F.decode(cell.value));
                        cell.badge = '';
                    }
                });
            });
            Tables.render(wrapper, data, {search: filtered ? 'x' : '', courseid: 0, status: '', perpage: table.perpage},
                exportUrl('csv'), 0);
            if (!data.total) {
                body.querySelector('.orgr-empty-table strong').textContent = F.str(filtered ? 'notxmatch' : 'norows');
                body.querySelector('.orgr-empty-table span:last-child').textContent = F.str(filtered ? 'notxmatchhint' :
                    'norowsperiod');
            }
            return;
        }).catch(function(error) {
            if (mine === requestid) {
                F.logError('transaction list failed', error);
                Tables.error(wrapper);
            }
        });
    };

    /**
     * Load summary, charts and filter options, then the list.
     */
    var load = function() {
        requestid++;
        var mine = requestid;
        var body = root.querySelector('[data-region="body"]');
        DateFilter.showError(root, '');
        setBusy(true);
        if (!body.querySelector('.orgr-kpis')) {
            body.innerHTML = '<div class="orgr-kpis">' + new Array(5).join('<div class="orgr-kpi orgr-skeleton"><span></span>' +
                '<span></span><span></span></div>') + '</div><div class="visually-hidden">' + F.esc(F.str('loading')) +
                '</div>';
        } else {
            body.classList.add('orgr-dim');
        }
        updateUrl();
        call('report_orgreports_get_payment_report', args()).then(function(data) {
            if (mine !== requestid) {
                return;
            }
            if (!data || !Array.isArray(data.cards) || !data.filters || !data.access) {
                throw new Error('unexpected payment report response');
            }
            ['charts', 'insights', 'notices', 'availability', 'tables'].forEach(function(k) {
                if (!Array.isArray(data[k])) {
                    data[k] = [];
                }
            });
            F.config().access = data.access;
            state.from = data.from || state.from;
            state.to = data.to || state.to;
            DateFilter.setDates(root, data.from, data.to);
            renderFilters(data.filters);
            root.querySelector('[data-region="orgname"]').textContent = F.decode(data.organisation);
            root.querySelector('[data-region="period"]').textContent = data.period;
            root.querySelector('[data-region="updated"]').textContent = F.timeNow();
            var link = root.querySelector('[data-region="dashboardlink"]');
            var url = new URL(link.href, window.location.href);
            url.searchParams.set('org', String(state.org));
            link.href = url.toString();
            var exportregion = root.querySelector('[data-region="export"]');
            if (exportregion) {
                exportregion.classList.toggle('d-none', !data.access.canexport);
            }
            Charts.destroyAll();
            body.classList.remove('orgr-dim');
            body.innerHTML = Cards.render(data.cards) +
                (data.insights.length ? '<section class="orgr-insights"><i class="fa-solid fa-lightbulb" aria-hidden="true">' +
                    '</i><div><h3 class="orgr-insights-title">' + F.esc(F.str('insights')) + '</h3><ul>' +
                    data.insights.map(function(i) {
                        return '<li>' + i + '</li>';
                    }).join('') + '</ul></div></section>' : '') +
                '<div class="orgr-charts" data-region="charts"></div>' +
                data.tables.map(function(t) {
                    return Tables.shell(t, {search: '', courseid: 0, status: '', perpage: table.perpage}, [],
                        data.access.canexport, {simple: true});
                }).join('') + renderAbout(data);
            Charts.render(body.querySelector('[data-region="charts"]'), data.charts);
            setBusy(false);
            loadTable();
            return;
        }).catch(function(error) {
            if (mine !== requestid) {
                return;
            }
            F.logError('payment report failed', error);
            Charts.destroyAll();
            setBusy(false);
            body.classList.remove('orgr-dim');
            var denied = error && (error.errorcode === 'nopermissions' || error.errorcode === 'noaccess');
            body.innerHTML = '<div class="orgr-panel orgr-state orgr-state-error" role="alert"><span class="orgr-empty-icon ' +
                'orgr-empty-icon-error" aria-hidden="true"><i class="fa-solid fa-triangle-exclamation"></i></span><div>' +
                '<strong>' + F.esc(F.str(denied ? 'nopermission' : 'loadfailed')) + '</strong><span>' +
                F.esc(F.str(denied ? 'nopermissionhint' : 'loadfailedhint')) + '</span>' + (denied ? '' :
                '<button type="button" class="orgr-btn orgr-btn-primary" data-action="retry"><i class="fa-solid ' +
                'fa-rotate-right" aria-hidden="true"></i> ' + F.esc(F.str('retry')) + '</button>') + '</div></div>';
        });
    };

    /**
     * Data sources and calculation rules.
     *
     * @param {Object} data
     * @returns {String}
     */
    var renderAbout = function(data) {
        var notes = data.notices.map(function(n) {
            return '<div class="orgr-note orgr-note-' + F.esc(n.type) + '"><i class="fa-solid fa-circle-info" ' +
                'aria-hidden="true"></i><div><strong>' + n.title + '</strong><p>' + n.text + '</p></div></div>';
        }).join('');
        var icons = {measured: 'fa-circle-check', estimated: 'fa-wave-square', unavailable: 'fa-ban'};
        var avail = data.availability.map(function(r) {
            return '<div class="orgr-avail orgr-avail-' + F.esc(r.status) + '"><div class="orgr-avail-top"><span ' +
                'class="orgr-avail-metric">' + F.esc(r.metric) + '</span><span class="orgr-status orgr-status-' +
                F.esc(r.status) + '"><i class="fa-solid ' + (icons[r.status] || 'fa-circle') + '" aria-hidden="true"></i> ' +
                F.esc(r.statuslabel) + '</span></div><p class="orgr-avail-source">' + r.source + '</p></div>';
        }).join('');
        if (!notes && !avail) {
            return '';
        }
        return '<details class="orgr-about"><summary><i class="fa-solid fa-circle-info" aria-hidden="true"></i><span>' +
            F.esc(F.str('aboutdata')) + '</span><i class="fa-solid fa-chevron-down orgr-caret" aria-hidden="true"></i>' +
            '</summary><div class="orgr-about-list">' + notes + '</div>' +
            (avail ? '<div class="orgr-avail-grid orgr-about-avail">' + avail + '</div>' : '') + '</details>';
    };

    /**
     * Open a transaction.
     *
     * @param {String} txid
     * @param {HTMLElement} trigger
     */
    var openDetail = function(txid, trigger) {
        if (!Detail.isOpen(root)) {
            Detail.open(root, trigger);
        }
        call('report_orgreports_get_payment_detail', {org: state.org, txid: txid}).then(function(data) {
            Detail.render(root, data);
            return;
        }).catch(function(error) {
            F.logError('transaction detail failed', error);
            Detail.error(root, txid);
        });
    };

    /**
     * Apply the From / To fields.
     */
    var applyCustom = function() {
        var from = root.querySelector('[data-field="from"]').value;
        var to = root.querySelector('[data-field="to"]').value;
        var message = DateFilter.validate(from, to, F.config().today);
        DateFilter.showError(root, message);
        if (message) {
            return;
        }
        state.range = 'custom';
        state.from = from;
        state.to = to;
        DateFilter.setPreset(root, 'custom');
        table.page = 0;
        load();
    };

    /**
     * Wait for typing to stop.
     *
     * @param {Function} fn
     * @param {Number} wait
     * @returns {Function}
     */
    var debounce = function(fn, wait) {
        var timer;
        return function() {
            var a = arguments;
            clearTimeout(timer);
            timer = setTimeout(function() {
                fn.apply(null, a);
            }, wait);
        };
    };

    var searchChanged = debounce(function(value) {
        state.filters.search = value.trim();
        table.page = 0;
        load();
    }, 400);

    var listen = function() {
        root.addEventListener('change', function(e) {
            var t = e.target;
            if (t.dataset.action === 'org') {
                state.org = parseInt(t.value, 10);
                // Courses, plans and methods differ per organisation.
                state.filters.courseid = 0;
                state.filters.planid = 0;
                state.filters.method = '';
                table.page = 0;
                load();
            } else if (t.dataset.pfilter && t.dataset.pfilter !== 'search') {
                var key = t.dataset.pfilter;
                state.filters[key] = key === 'courseid' || key === 'planid' ? F.toNumber(t.value) : t.value;
                table.page = 0;
                load();
            } else if (t.dataset.filter === 'perpage') {
                table.perpage = F.toNumber(t.value) || 25;
                table.page = 0;
                loadTable();
            }
        });
        root.addEventListener('input', function(e) {
            if (e.target.dataset.pfilter === 'search') {
                searchChanged(e.target.value);
            }
            if (e.target.dataset.field) {
                DateFilter.showError(root, '');
            }
        });
        root.addEventListener('submit', function(e) {
            e.preventDefault();
        });
        root.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' && e.target.dataset.field) {
                e.preventDefault();
                applyCustom();
            } else if (e.key === 'Escape') {
                if (Detail.isOpen(root)) {
                    Detail.close(root);
                } else {
                    toggleMenu(false);
                }
            }
        });
        document.addEventListener('click', function(e) {
            var menu = root.querySelector('[data-region="exportlist"]');
            if (menu && !menu.hidden && !(e.target.closest && e.target.closest('[data-region="export"]'))) {
                toggleMenu(false);
            }
        });
        root.addEventListener('click', function(e) {
            var target = e.target.closest('[data-range],[data-action],[data-sort],[data-page]');
            if (!target || target.disabled) {
                return;
            }
            var action = target.dataset.action;
            if (target.dataset.range) {
                if (target.dataset.range === 'custom') {
                    DateFilter.setPreset(root, 'custom');
                    root.querySelector('[data-field="from"]').focus();
                } else {
                    state.range = target.dataset.range;
                    DateFilter.setPreset(root, state.range);
                    table.page = 0;
                    load();
                }
            } else if (action === 'applycustom') {
                applyCustom();
            } else if (action === 'refresh' || action === 'retry') {
                load();
            } else if (action === 'retrytable') {
                loadTable();
            } else if (action === 'resetfilters') {
                e.preventDefault();
                FILTERS.forEach(function(k) {
                    state.filters[k] = k === 'courseid' || k === 'planid' ? 0 : '';
                });
                root.querySelector('[data-pfilter="search"]').value = '';
                table.page = 0;
                load();
            } else if (action === 'menu') {
                toggleMenu(root.querySelector('[data-region="exportlist"]').hidden);
            } else if (action === 'detail') {
                openDetail(target.dataset.txid, target);
            } else if (action === 'closedetail') {
                Detail.close(root);
            } else if (action === 'tablecsv' && target.classList.contains('disabled')) {
                e.preventDefault();
            } else if (target.dataset.sort) {
                table.dir = table.sort === target.dataset.sort && table.dir === 'ASC' ? 'DESC' : 'ASC';
                table.sort = target.dataset.sort;
                table.page = 0;
                loadTable();
            } else if (target.dataset.page !== undefined) {
                table.page = Math.max(0, parseInt(target.dataset.page, 10));
                loadTable();
            }
        });
    };

    return {
        /**
         * Start the Payment Reports page.
         *
         * @param {String} selector
         */
        init: function(selector) {
            root = document.querySelector(selector);
            if (!root) {
                return;
            }
            var config;
            try {
                config = JSON.parse(root.dataset.config);
            } catch (e) {
                F.logError('page configuration', e);
                return;
            }
            F.init(config);
            var f = config.filters || {};
            state = {org: config.org, range: config.range, from: config.from, to: config.to, filters: {
                status: f.status || '', method: f.method || '', courseid: F.toNumber(f.courseid), planid: F.toNumber(f.planid),
                search: f.search || ''}};
            listen();
            load();
        }
    };
});
